// Deterministic reference snapshots generated by scripts/buffer-reflow-oracle.mjs.
use std::{cell::RefCell, rc::Rc};
use xterm_core::{
    buffer::{reflow::*, BufferLine, CellData, ExtendedAttrs},
    circular_list::CircularList,
};
type Line = Rc<RefCell<BufferLine>>;
fn numbers(value: &str) -> Vec<usize> {
    if value == "-" {
        return vec![];
    }
    value.split(',').map(|n| n.parse().unwrap()).collect()
}
fn units(value: &str) -> Vec<u16> {
    if value == "-" {
        return vec![];
    }
    value
        .split('.')
        .map(|n| u16::from_str_radix(n, 16).unwrap())
        .collect()
}
fn rows(value: &str) -> Vec<Line> {
    if value == "-" {
        return vec![];
    }
    value
        .split('|')
        .map(|row| {
            let (header, data) = row.split_once(';').unwrap();
            let header = numbers(header);
            let cells: Vec<_> = data.split(';').filter(|c| !c.is_empty()).collect();
            let mut line = BufferLine::new(cells.len(), None, header[0] != 0);
            for (i, cell) in cells.iter().enumerate() {
                let (fields, text) = cell.rsplit_once(',').unwrap();
                let fields: Vec<u32> = fields.split(',').map(|v| v.parse().unwrap()).collect();
                let mut cell = CellData {
                    content: fields[0],
                    combined_data: units(text),
                    ..CellData::default()
                };
                cell.fg = fields[1];
                cell.bg = fields[2];
                cell.extended = ExtendedAttrs::new(fields[3], u64::from(fields[4]));
                line.set_cell(i, &cell);
            }
            Rc::new(RefCell::new(line))
        })
        .collect()
}
fn join(values: impl IntoIterator<Item = impl ToString>, separator: &str) -> String {
    let result = values
        .into_iter()
        .map(|v| v.to_string())
        .collect::<Vec<_>>()
        .join(separator);
    if result.is_empty() {
        "-".into()
    } else {
        result
    }
}
fn snapshot(rows: &[Line]) -> String {
    join(
        rows.iter().map(|row| {
            let row = row.borrow();
            let cells = (0..row.len())
                .map(|i| {
                    let cell = row.get_cell(i).unwrap();
                    let text = join(cell.get_chars().iter().map(|u| format!("{u:x}")), ".");
                    format!(
                        "{},{},{},{},{},{text}",
                        cell.content,
                        cell.fg,
                        cell.bg,
                        cell.extended.ext(),
                        cell.extended.url_id()
                    )
                })
                .collect::<Vec<_>>()
                .join(";");
            format!(
                "{},{};{cells}",
                u8::from(row.is_wrapped),
                row.get_trimmed_length()
            )
        }),
        "|",
    )
}
fn widening(rows: &[Line], old: usize, new: usize, cursor: usize, allow: bool) -> String {
    let null = BufferLine::new(1, None, false).get_cell(0).unwrap();
    let lines = Rc::new(CircularList::new(rows.len() + 8).unwrap());
    for row in rows {
        row.borrow_mut().resize(new, &null);
        lines.push(row.clone()).unwrap();
    }
    let removals =
        reflow_larger_get_lines_to_remove(&lines, old, new, cursor, &null, allow).unwrap();
    let events = Rc::new(RefCell::new(Vec::new()));
    let captured = events.clone();
    let weak = Rc::downgrade(&lines);
    lines.on_delete_emitter.event().subscribe(move |event| {
        captured.borrow_mut().push(format!(
            "{},{},{}",
            event.index,
            event.amount,
            weak.upgrade().unwrap().len()
        ));
    });
    let layout = reflow_larger_create_new_layout(&lines, &removals).unwrap();
    let current = || {
        (0..lines.len())
            .map(|i| lines.get(i).unwrap())
            .collect::<Vec<_>>()
    };
    let before = snapshot(&current());
    reflow_larger_apply_new_layout(&lines, &layout.layout).unwrap();
    let identities = join(
        current()
            .iter()
            .map(|row| rows.iter().position(|r| Rc::ptr_eq(row, r)).unwrap()),
        ",",
    );
    let result = format!(
        "{}#{}#{}#{}#{before}#{}#{identities}",
        join(removals.iter().flat_map(|&(a, b)| [a, b]), ","),
        join(layout.layout, ","),
        layout.count_removed,
        join(events.borrow().iter(), ";"),
        snapshot(&current())
    );
    result
}
#[test]
fn seeded_full_cell_layout_and_identity_snapshots() {
    for (index, trace) in include_str!("fixtures/buffer-reflow.tsv")
        .lines()
        .enumerate()
    {
        let fields: Vec<_> = trace.split('\t').collect();
        let old = fields[1].parse().unwrap();
        let new = fields[2].parse().unwrap();
        let rows = rows(fields[5]);
        assert_eq!(snapshot(&rows), fields[5], "input case {index}");
        let actual = if fields[0] == "L" {
            widening(
                &rows,
                old,
                new,
                fields[3].parse().unwrap(),
                fields[4] == "1",
            )
        } else {
            join(
                reflow_smaller_get_new_line_lengths(&rows, old, new).unwrap(),
                ",",
            )
        };
        assert_eq!(
            actual, fields[6],
            "case {index}, seed 0xb0ffef10, trace {trace}"
        );
    }
}
